CREATE DATABASE IF NOT EXISTS crs_railway CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE crs_railway;

CREATE TABLE IF NOT EXISTS stations (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(8) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS routes (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, train_code VARCHAR(12) NOT NULL, from_station_id INT NOT NULL, to_station_id INT NOT NULL, base_fare DECIMAL(8,2) NOT NULL, CONSTRAINT fk_route_from FOREIGN KEY(from_station_id) REFERENCES stations(id), CONSTRAINT fk_route_to FOREIGN KEY(to_station_id) REFERENCES stations(id), CHECK(from_station_id<>to_station_id));
CREATE TABLE IF NOT EXISTS trips (id INT AUTO_INCREMENT PRIMARY KEY, route_id INT NOT NULL, depart_at DATETIME NOT NULL, arrive_at DATETIME NOT NULL, CONSTRAINT fk_trip_route FOREIGN KEY(route_id) REFERENCES routes(id));
CREATE TABLE IF NOT EXISTS trip_seats (id INT AUTO_INCREMENT PRIMARY KEY, trip_id INT NOT NULL, seat_code VARCHAR(4) NOT NULL, status ENUM('available','reserved') NOT NULL DEFAULT 'available', UNIQUE KEY uq_trip_seat(trip_id,seat_code), CONSTRAINT fk_seat_trip FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL DEFAULT 'staff', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookings (id INT AUTO_INCREMENT PRIMARY KEY, reference CHAR(8) NOT NULL UNIQUE, trip_id INT NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(24) NOT NULL, total_fare DECIMAL(9,2) NOT NULL, status ENUM('confirmed','cancelled','changed') NOT NULL DEFAULT 'confirmed', concession ENUM('adult','student','senior') NOT NULL DEFAULT 'adult', refund_amount DECIMAL(9,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_booking_trip FOREIGN KEY(trip_id) REFERENCES trips(id));
CREATE TABLE IF NOT EXISTS passengers (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, full_name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(24) NOT NULL, CONSTRAINT fk_passenger_booking FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS booking_seats (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, trip_seat_id INT NOT NULL, seat_code VARCHAR(4) NOT NULL, UNIQUE KEY uq_booking_seat(booking_id,trip_seat_id), CONSTRAINT fk_bs_booking FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, CONSTRAINT fk_bs_trip_seat FOREIGN KEY(trip_seat_id) REFERENCES trip_seats(id));
CREATE TABLE IF NOT EXISTS booking_events (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, event_type VARCHAR(24) NOT NULL, note VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_event_booking FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);

